<?php defined('BASEPATH') OR exit('No direct script access allowed');class Workflows extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Workflow_model','workflows');}function index(){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(trim($d['name']??'')===''||strlen($d['name'])>120)return $this->fail('VALIDATION_ERROR','Valid workflow name required',422);return $this->respond($this->workflows->save(NULL,$this->c['organizationId'],$this->c['sub'],$d),201);}$p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:20)));return $this->respond($this->workflows->listing($this->c['organizationId'],$this->input->get('status'),$p,$pp));}function item($id){$m=$this->input->method(TRUE);if($m==='GET')$r=$this->workflows->one($id,$this->c['organizationId']);elseif($m==='DELETE'){if($this->workflows->remove($id,$this->c['organizationId']))return $this->respond(array());$r=NULL;}else $r=$this->workflows->save($id,$this->c['organizationId'],$this->c['sub'],$this->body());return $r?$this->respond($r):$this->fail('NOT_FOUND','Workflow not found',404);}function run_workflow($id){$d=$this->body();$made=$this->workflows->create_run($id,$this->c['organizationId'],$this->c['sub'],$d);if(!$made)return $this->fail('NOT_FOUND','Workflow not found',404);$ctx=array('input'=>$d['input']??array());$records=array();$status='SUCCEEDED';$error=NULL;$this->load->library('Ai_provider');foreach(json_decode($made['workflow']['nodes'],TRUE)?:array() as $node){$start=date('c');$out=array();$ns='SUCCEEDED';switch($node['type']??''){case 'TRIGGER':$out=$ctx['input'];break;case 'END':$out=array('completed'=>TRUE,'finishedAt'=>date('c'));break;case 'ACTION':$action=$node['config']['action']??'';if($action==='log')$out=array('logged'=>$node['config']['message']??'');elseif($action==='createTask'){$tid=$this->uuid();$title=$this->render($node['config']['title']??'Workflow task',$ctx);$this->db->insert('tasks',array('id'=>$tid,'organization_id'=>$this->c['organizationId'],'title'=>$title,'description'=>$this->render($node['config']['description']??'',$ctx),'status'=>'TODO','priority'=>$node['config']['priority']??'MEDIUM','progress'=>0,'creator_id'=>$this->c['sub'],'agent_id'=>$node['config']['agentId']??NULL,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));$out=array('taskId'=>$tid,'title'=>$title);}elseif($action==='createActionItem'){$aid=$this->uuid();$this->db->insert('action_items',array('id'=>$aid,'organization_id'=>$this->c['organizationId'],'title'=>$this->render($node['config']['title']??'Action item',$ctx),'description'=>$this->render($node['config']['description']??'',$ctx),'status'=>'OPEN','priority'=>$node['config']['priority']??'MEDIUM','channel_id'=>$node['config']['channelId']??NULL,'assignee_id'=>$node['config']['assigneeId']??NULL,'created_by_id'=>$this->c['sub'],'metadata'=>'{}','created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));$out=array('actionItemId'=>$aid);}elseif($action==='sendMessage'&&!empty($node['config']['channelId'])){$mid=$this->uuid();$now=date('Y-m-d H:i:s');$this->db->insert('talk_messages',array('id'=>$mid,'channel_id'=>$node['config']['channelId'],'type'=>'TEXT','content'=>$this->render($node['config']['message']??'(workflow message)',$ctx),'user_id'=>$this->c['sub'],'reply_count'=>0,'reactions'=>'{}','metadata'=>'{}','created_at'=>$now,'updated_at'=>$now));$out=array('messageId'=>$mid);}else{$ns='FAILED';$error='Unsupported or invalid PHP workflow action: '.($action?:'none');}break;case 'CONDITION':$expr=$node['config']['expr']??'true';$out=array('result'=>$this->condition($expr,$ctx));break;case 'LOOP':$path=$node['config']['collectionPath']??'items';$items=$this->path($ctx,$path);$items=is_array($items)?array_slice($items,0,20):array();$iterations=array();foreach($items as $i=>$item)$iterations[]=array('index'=>$i,'item'=>$item);$out=array('iterations'=>$iterations,'count'=>count($iterations));break;case 'DELAY':$ms=min(5000,max(0,(int)($node['config']['delayMs']??1000)));usleep($ms*1000);$out=array('delayed'=>$ms,'cappedAtMs'=>5000);break;case 'AI':$res=$this->ai_provider->complete(array(array('role'=>'system','content'=>$node['config']['systemPrompt']??'You are a workflow AI node.'),array('role'=>'user','content'=>$node['config']['prompt']??$node['label'])),$node['config']['modelId']??NULL);if($res['ok'])$out=array('result'=>$res['content']);else{$ns='FAILED';$error=$res['message'];}break;case 'APPROVAL':if(!empty($node['config']['requireHuman'])){$ns='WAITING_APPROVAL';$status='WAITING_APPROVAL';$out=array('approved'=>FALSE,'pending'=>TRUE);}break;default:$out=array('note'=>'Node persisted but has no PHP executor');}$records[]=array('nodeId'=>$node['id'],'status'=>$ns,'startedAt'=>$start,'endedAt'=>date('c'),'output'=>$out,'error'=>$ns==='FAILED'?$error:NULL,'attempts'=>1);$ctx[$node['id']]=$out;if($ns==='FAILED'){$status='FAILED';break;}if($ns==='WAITING_APPROVAL')break;}$run=$this->workflows->finish_run($made['run']['id'],$status,$ctx,$records,$error);$this->load->library('Webhook_dispatcher');$this->webhook_dispatcher->dispatch($this->c['organizationId'],'workflow.run.'.strtolower($status),array('workflowId'=>$id,'runId'=>$run['id'],'status'=>$run['status']));return $this->respond($run,201);}function runs(){ $p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:20)));return $this->respond($this->workflows->runs($this->c['organizationId'],$this->input->get('workflowId'),$this->input->get('status'),$p,$pp));}function run_item($id){$r=$this->workflows->run($id,$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Workflow run not found',404);}function approve($id){$d=$this->body();if(!isset($d['approved']))return $this->fail('VALIDATION_ERROR','approved is required',422);$r=$this->workflows->control($id,$this->c['organizationId'],'approve',(bool)$d['approved'],$d['feedback']??NULL);return $r?$this->respond($r):$this->fail('NOT_FOUND','Workflow run not found',404);}function cancel($id){$r=$this->workflows->control($id,$this->c['organizationId'],'cancel');return $r?$this->respond(array()):$this->fail($r===FALSE?'CONFLICT':'NOT_FOUND',$r===FALSE?'Completed runs cannot be cancelled':'Workflow run not found',$r===FALSE?409:404);}function analytics(){return $this->respond($this->workflows->analytics($this->c['organizationId']));}private function path($data,$path){foreach(explode('.',$path) as $key){if(!is_array($data)||!array_key_exists($key,$data))return NULL;$data=$data[$key];}return $data;}private function render($text,$ctx){return preg_replace_callback('/\{\{\s*([\w.]+).*?\}\}/',function($m)use($ctx){$v=$this->path($ctx,$m[1]);return is_scalar($v)?(string)$v:'';},$text);}private function condition($expr,$ctx){if($expr==='true')return TRUE;if($expr==='false')return FALSE;if(preg_match('/^([\w.]+)\s*(==|!=|>=|<=|>|<)\s*[\"\']?(.*?)[\"\']?$/',$expr,$m)){$l=$this->path($ctx,$m[1]);$r=$m[3];switch($m[2]){case'==':return$l==$r;case'!=':return$l!=$r;case'>':return$l>$r;case'<':return$l<$r;case'>=':return$l>=$r;case'<=':return$l<=$r;}}return(bool)$this->path($ctx,$expr);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
